INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1153, 'el_GR', 'origin (passkey/web origin)', 'προέλευση', 'fem.; plural προελεύσεις; first mention may gloss (origin)', NULL, 'Passkey/web origin (related_origins field, hint, API errors). 5 shipped hits, incl. emailtools "Origin host" = Διακομιστής προέλευσης [round 0930]', '2026-09-30 09:10:51', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1154, 'el_GR', 'session handle', 'λαβή συνεδρίας', 'fem.; kept distinct from session ID = ID συνεδρίας', NULL, 'Admin sessions column, field and search placeholder. 3 shipped hits [round 0930]', '2026-09-30 09:10:51', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1155, 'el_GR', 'capped (result/scan limit)', 'περιορισμένος', 'agrees with its noun (Τα αποτελέσματα είναι περιορισμένα; Η διατήρηση είναι περιορισμένη); the count in a capped notice is a floor / lower bound = κατώτατο όριο', NULL, 'Capped list/scan notices. 4 shipped hits for περιορισμέν- (plus περιορίστηκε in sessions.scan.capped), 6 for κατώτατο όριο [round 0930]', '2026-09-30 09:10:51', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1157, 'eo', 'impersonate / impersonation', 'imiti / imitado', 'verb imiti, noun imitado (Imiti klienton; Ĉesi imitadon)', NULL, 'Admin view-as-customer feature; no earlier eo rendering. 8 shipped hits [round 0930]', '2026-09-30 09:10:51', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1158, 'eo', 'webhook', 'webhook', 'keep Latin script, lowercase; hyphen before eo endings and in compounds (webhook-oj, webhook-eventoj)', NULL, 'Stripe webhook events and pending-federated correlation strings. 12 shipped hits [round 0930]', '2026-09-30 09:10:51', '2026-10-04 00:55:53');
