INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1273, 'pt_PT', 'override (operator/admin)', 'substituição', 'verb substituir (Substituir estado); ''operator override'' → ''substituição pelo operador''; org-delete checkbox → ''opção de substituição''', NULL, 'Domain verification, entitlement, sign-in/signup and org-delete overrides; extends the shipped entitlements override → substituição. 27 shipped hits [round 0930]', '2026-09-30 09:11:02', '2026-10-04 00:55:53');
