INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1276, 'pt_PT', 'capped … count is a floor / lower bound', 'valor mínimo', 'both ''the count shown is a floor'' and ''the total is a lower bound'' → ''é um valor mínimo''; ''Results are capped'' → ''Os resultados estão limitados''', NULL, 'Scan-cap notices in admin customers/domains/colonel organizations lists and admin-billing stripeOrgs/webhookEvents/pendingFederated; matches the shipped stripeOrgs wording. 6 shipped hits [round 0930]', '2026-09-30 09:11:02', '2026-10-04 00:55:53');
