INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1331, 'uk', 'federated subscriptions', 'федеративні підписки', 'adjective agrees with підписки: федеративних підписок (gen. pl.)', NULL, '3 shipped hits (pendingFederated title, loadError, empty) [round 0930]', '2026-09-30 09:11:07', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1332, 'uk', 'web origin', 'джерело', 'web-origin sense; ''(origin)'' follows the first mention in originsHint and related_origins_invalid', NULL, '4 shipped hits (admin-domains configs.edit.originsHint, configs.fields.related_origins; api-domains-errors related_origins_*) [round 0930]', '2026-09-30 09:11:08', '2026-10-04 00:55:53');
