INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1334, 'uk', 'capped results (count is a floor)', 'нижня межа', 'instrumental: ''... є нижньою межею''; ''Results are capped'' = ''Результати обмежено''', NULL, '6 shipped hits (billing stripeOrgs/webhookEvents/pendingFederated capped, colonel.organizations.capped, customers.list.capped, domains.list.capped) [round 0930]', '2026-09-30 09:11:08', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1336, 'uk', 'IdP Entity ID / SP Entity ID / Assertion Consumer Service URL', 'IdP Entity ID / SP Entity ID / Assertion Consumer Service URL', 'keep English: SAML field names admins copy into their IdP; descriptive SAML labels are translated (Сертифікат підпису IdP)', NULL, '4 shipped hits (sso.idp_entity_id, sp_entity_id, acs_url, test_connection_hint_saml Entity ID); same treatment as shipped Client ID and Tenant ID [round 0930]', '2026-09-30 09:11:08', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1339, 'vi', 'impersonate / impersonation', 'mạo danh', 'verb and noun; Impersonate customer = Mạo danh khách hàng; Stop impersonating = Dừng mạo danh', NULL, '8 shipped hits (web.impersonation.banner.*, web.admin.customers.actions.impersonate.*) [round 0930]', '2026-09-30 09:11:08', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1340, 'vi', 'elevation / elevated access', 'nâng quyền / quyền truy cập nâng cao', 'Drop elevation = Bỏ nâng quyền; elevated role = vai trò nâng cao; kept distinct from plan upgrade (nâng cấp) and role promotion (thăng cấp)', NULL, '4 shipped hits (web.admin.elevation.banner.*, customers.actions.unverify.confirmDescription) [round 0930]', '2026-09-30 09:11:08', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1341, 'vi', 'step-up authentication', 'xác thực tăng cường', 'bare ''step-up'' also renders xác thực tăng cường; kept distinct from two-factor (xác thực hai yếu tố)', NULL, '3 shipped hits (web.admin.elevation.errors.*) [round 0930]', '2026-09-30 09:11:08', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1342, 'vi', 'subscription', 'đăng ký', 'homonym of sign up (đăng ký, 43 shipped hits); disambiguate by collocation (đăng ký liên vùng, trạng thái đăng ký)', NULL, '61 shipped hits, no other rendering of subscription [round 0930]', '2026-09-30 09:11:08', '2026-10-04 00:55:53');
