INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1344, 'vi', 'blockers / Blocked:', 'trở ngại / Bị chặn:', 'Bị chặn: is the sentence-initial prefix on delete.blocked.* lines', NULL, '9 shipped hits (4 blockers in customers.actions.purge.*, 5 Blocked: in organizations.detail.delete.blocked.*) [round 0930]', '2026-09-30 09:11:09', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1345, 'vi', 'install (installation)', 'bản cài đặt', 'classifier bản required for the noun; kept distinct from deployment (bản triển khai)', NULL, '6 of 8 shipped hits; the 2 feature-translations keys use bare cài đặt (reported) [round 0930]', '2026-09-30 09:11:09', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1346, 'vi', 'origin (web origin)', 'nguồn gốc', 'web-origin sense; ''(origin)'' follows the first mention in originsHint', NULL, '4 shipped hits (admin-domains configs.edit.originsHint, configs.fields.related_origins; api-domains-errors related_origins_*) [round 0930]', '2026-09-30 09:11:09', '2026-10-04 00:55:53');
INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1347, 'vi', 'lower bound (capped scan)', 'giới hạn dưới', '''the total is a lower bound'' = ''tổng số là giới hạn dưới''', NULL, '3 shipped hits (billing stripeOrgs/webhookEvents/pendingFederated capped); the ''count shown is a floor'' strings (customers.list, domains.list, colonel.organizations capped) use mức tối thiểu [round 0930]', '2026-09-30 09:11:09', '2026-10-04 00:55:53');
