INSERT INTO glossary (id, locale, term, translation, context, alternatives, notes, created_at, updated_at) VALUES (1354, 'zh', 'purge preflight / teardown / blockers', '预检 / 拆除 / 阻止因素', 'the Blocked: prefix is 已阻止：', NULL, 'blockers: 4 shipped hits (customers.actions.purge.*) plus 5 已阻止： prefixes (organizations.detail.delete.blocked.*); preflight and teardown occur only in purge.confirmDescription; purge = 彻底删除 (row 499) [round 0930]', '2026-09-30 09:11:10', '2026-10-04 00:55:53');
